// ---------------------------------------------------------------------------
// WorkSense Qwen client — external OpenAI-compatible endpoint, called ONLY
// from backend functions. The model never computes scores; it only extracts
// structured data / writes rubric text. Resume text is treated as UNTRUSTED
// input: instruction-like phrases are neutralized and the content is wrapped
// in an explicit untrusted delimiter before any model call.
// ---------------------------------------------------------------------------

function getEnv(name: string, fallback: string): string {
  try {
    const deno = (globalThis as { Deno?: { env?: { get?: (n: string) => string | undefined } } }).Deno;
    const fromDeno = deno?.env?.get?.(name);
    if (fromDeno !== undefined) return fromDeno;
  } catch {
    /* node test env */
  }
  try {
    const fromNode = (typeof process !== "undefined" ? process.env?.[name] : undefined) ?? fallback;
    return fromNode;
  } catch {
    return fallback;
  }
}

export const QWEN_BASE_URL = getEnv(
  "QWEN_BASE_URL",
  "https://evolve-eternity-epidural.ngrok-free.dev/v1"
).replace(/\/+$/, "");
export const QWEN_MODEL = getEnv("QWEN_MODEL", "qwen3:4b-instruct-2507-q4_K_M");
export const QWEN_API_KEY = getEnv("QWEN_API_KEY", "local");

// ---------------------------------------------------------------------------
// Untrusted-content handling (resume intake)
// ---------------------------------------------------------------------------

const INSTRUCTION_PATTERNS: RegExp[] = [
  /\bignore\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context|messages?|output)\b/gi,
  /\bdisregard\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context)\b/gi,
  /\bdo\s+not\s+(?:follow|obey|listen\s+to)\b/gi,
  /\byou\s+are\s+now\b/gi,
  /\bsystem\s+prompt\b/gi,
  /\bdeveloper\s+message\b/gi,
  /\bjailbreak\b/gi,
  /\boverride\s+(?:(?:your|the|system|developer)\s+)*(?:instructions?|rules?|prompt)\b/gi,
  /\bpretend\s+(?:to\s+|that\s+|you\s+)/gi,
  /\bsay\s+you\s+(?:are|have|would|can)\b/gi,
  /\bgive\s+(?:me\s+)?(?:a\s+)?100\s*%?\s*(?:match|fit|score)\b/gi,
  /\balways\s+(?:ignore|follow|obey)\b/gi,
  /\breveal\s+(?:your|the)\s+(?:system|instructions?|prompt)\b/gi,
];

/** Neutralize instruction-like phrases in untrusted resume text. */
export function sanitizeUntrusted(text: string): string {
  let out = String(text ?? "");
  for (const re of INSTRUCTION_PATTERNS) {
    out = out.replace(re, "[redacted]");
  }
  return out.trim();
}

/** Explicit delimiter marking untrusted content for the model. */
export function wrapUntrusted(text: string): string {
  return `<untrusted_input>\n${text}\n</untrusted_input>`;
}

// ---------------------------------------------------------------------------
// OpenAI-compatible chat call
// ---------------------------------------------------------------------------

function extractJson(content: string): unknown {
  const trimmed = content.trim();
  // Strip markdown fences if present.
  const fenced = trimmed.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
  const start = fenced.indexOf("{");
  const end = fenced.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) {
    throw new Error(`qwen: no JSON object in response: ${content.slice(0, 200)}`);
  }
  return JSON.parse(fenced.slice(start, end + 1));
}

export async function callQwen(params: {
  system: string;
  user: string;
  json?: boolean;
  maxTokens?: number;
  temperature?: number;
}): Promise<unknown> {
  const body: Record<string, unknown> = {
    model: QWEN_MODEL,
    messages: [
      { role: "system", content: params.system },
      { role: "user", content: params.user },
    ],
    temperature: params.temperature ?? 0.2,
    max_tokens: params.maxTokens ?? 1600,
    stream: false,
  };
  if (params.json) {
    body.response_format = { type: "json_object" };
  }

  let res: Response;
  try {
    res = await fetch(`${QWEN_BASE_URL}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${QWEN_API_KEY}`,
      },
      body: JSON.stringify(body),
    });
  } catch (err) {
    throw new Error(`qwen: network error (is the endpoint reachable?): ${err instanceof Error ? err.message : String(err)}`);
  }

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`qwen: HTTP ${res.status}: ${text.slice(0, 300)}`);
  }

  const data = await res.json();
  const content = data?.choices?.[0]?.message?.content;
  if (typeof content !== "string" || content.length === 0) {
    throw new Error("qwen: empty completion");
  }
  if (params.json) {
    return extractJson(content);
  }
  return content;
}


// ---------------------------------------------------------------------------
// WorkSense Grounded Policy engine — DETERMINISTIC retrieval, zero LLM.
//  - paragraph-level policy chunks (stable doc_code + section heading)
//  - BM25-style relevance scoring (no LLM credits)
//  - calibrated abstention gate evaluated BEFORE any model call
//  - citation validator so an ungrounded answer can never slip through
// ---------------------------------------------------------------------------

export interface PolicyDoc {
  id: string;
  title: string;
  category: string;
  doc_code: string;
  effective_date?: string;
  summary?: string;
  sections: { code: string; heading: string; text: string }[];
}

export interface PolicyChunk {
  doc_code: string;
  doc_title: string;
  category: string;
  section_code: string;
  heading: string;
  text: string;
}

export interface RetrievedChunk extends PolicyChunk {
  score: number;
}

/** Calibrated on the seeded policy corpus. Questions below this skip the LLM. */
export const ABSTENTION_THRESHOLD = 0.75;

const STOPWORDS = new Set([
  "a", "an", "the", "to", "of", "in", "on", "for", "and", "or", "with", "is", "are", "be", "at",
  "by", "from", "as", "it", "its", "i", "you", "your", "we", "our", "can", "may", "must", "will",
  "not", "no", "that", "this", "these", "those", "per", "up", "over", "if", "when", "who", "what",
  "which", "how", "do", "does", "did", "have", "has", "had", "would", "should", "could", "about",
  "all", "any", "each", "every", "more", "most", "other", "some", "such", "than", "then", "there",
  "they",   "their", "into", "within", "after", "before", "during", "between", "out", "off", "under",
  "above", "does", "s", "t",
]);

export function tokenize(text: string): string[] {
  return String(text ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9\s'-]/g, " ")
    .split(/\s+/)
    .map((t) => t.replace(/^['-]+|['-]+$/g, ""))
    .filter((t) => t.length > 1 && !STOPWORDS.has(t));
}

export function flattenPolicies(policies: PolicyDoc[]): PolicyChunk[] {
  const chunks: PolicyChunk[] = [];
  for (const p of policies) {
    for (const s of p.sections) {
      chunks.push({
        doc_code: p.doc_code,
        doc_title: p.title,
        category: p.category,
        section_code: s.code,
        heading: s.heading,
        text: s.text,
      });
    }
  }
  return chunks;
}

const K1 = 1.2;
const B = 0.75;

/** Classic BM25 over the flattened chunk corpus. */
export function retrieveChunks(policies: PolicyDoc[], question: string, topK = 3): RetrievedChunk[] {
  const chunks = flattenPolicies(policies);
  const N = chunks.length;
  const avgdl = chunks.reduce((s, c) => s + tokenize(c.text).length, 0) / Math.max(1, N);
  const queryTerms = tokenize(question);

  // document frequency per term
  const df = new Map<string, number>();
  const docTokens = chunks.map((c) => {
    const tokens = tokenize(c.text);
    const uniq = new Set(tokens);
    for (const t of uniq) df.set(t, (df.get(t) ?? 0) + 1);
    return tokens;
  });

  const idf = (term: string) => Math.log(1 + (N - (df.get(term) ?? 0) + 0.5) / ((df.get(term) ?? 0) + 0.5));

  const scored: RetrievedChunk[] = chunks.map((c, i) => {
    const tokens = docTokens[i];
    const dl = tokens.length;
    let score = 0;
    for (const t of queryTerms) {
      const tf = tokens.filter((x) => x === t).length;
      if (tf === 0) continue;
      score += ((tf * (K1 + 1)) / (tf + K1 * (1 - B + (B * dl) / avgdl))) * idf(t);
    }
    return { ...c, score };
  });

  return scored.sort((a, b) => b.score - a.score).slice(0, topK);
}

/** Fuzzy normalization for quote matching (whitespace + case insensitive). */
export function normalizeForMatch(s: string): string {
  return String(s ?? "").toLowerCase().replace(/\s+/g, " ").trim();
}

export interface Citation {
  claim?: string;
  doc_code?: string;
  section?: string;
  exact_quote?: string;
}

/**
 * Every citation's quote must actually appear (fuzzily) in a retrieved chunk.
 * Invalid citations are dropped; returns { valid, droppedCount }.
 */
export function validateCitations(citations: Citation[] | undefined, chunks: RetrievedChunk[]): {
  valid: Citation[];
  droppedCount: number;
} {
  const valid: Citation[] = [];
  let dropped = 0;
  for (const c of citations ?? []) {
    const quote = normalizeForMatch(c.exact_quote ?? "");
    if (!quote) {
      dropped++;
      continue;
    }
    const found = chunks.some((ch) => normalizeForMatch(ch.text).includes(quote));
    if (found && c.doc_code && c.section) {
      valid.push(c);
    } else {
      dropped++;
    }
  }
  return { valid, droppedCount: dropped };
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";



const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const GROUNDING_SYSTEM = `You are the WorkSense HR Policy Reasoning Agent. Answer using ONLY the provided policy excerpts. If they do not contain the answer, set status to "insufficient_evidence" and say so plainly — never invent a policy. Every claim must cite doc_code, section, and a short exact quote.
Respond with JSON only:
{"status":"grounded_response|insufficient_evidence","answer":"string","citations":[{"doc_code":"string","section":"string","exact_quote":"string"}]}`;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHORIZED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, org_id")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHORIZED" }, 401);

  let body: { question?: string } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const raw = String(body.question ?? "").trim();
  if (raw.length < 5) return json({ error: "BAD_REQUEST", message: "Ask a real question (min 5 characters)." }, 400);

  // Untrusted input handling: neutralize instruction-like phrases.
  const question = sanitizeUntrusted(raw);

  const { data: org } = await supabase
    .from("organizations")
    .select("policies")
    .eq("id", caller.org_id)
    .maybeSingle();
  const policies = (org?.policies ?? []) as PolicyDoc[];

  // 1) DETERMINISTIC retrieval — zero LLM credits.
  const retrieval = retrieveChunks(policies, question, 3);

  // 2) CALIBRATED ABSTENTION GATE — before any model call.
  if (retrieval.length === 0 || retrieval[0].score < ABSTENTION_THRESHOLD) {
    return json({
      status: "insufficient_evidence",
      abstained: true,
      best_score: retrieval[0]?.score ?? 0,
      threshold: ABSTENTION_THRESHOLD,
      answer: "",
      citations: [],
      retrieval,
    });
  }

  // 3) ONE grounded Qwen call per question that clears the threshold.
  const chunksText = retrieval
    .map((c) => `[${c.doc_code} ${c.section_code}] ${c.heading}
${c.text}`)
    .join("\n\n");

  const parsed = (await callQwen({
    json: true,
    temperature: 0.1,
    maxTokens: 900,
    system: GROUNDING_SYSTEM,
    user: `<policy_chunks>
${chunksText}
</policy_chunks>

Question (untrusted): ${wrapUntrusted(question)}`,
  })) as {
    status?: string;
    answer?: string;
    citations?: { doc_code?: string; section?: string; exact_quote?: string }[];
  };

  // Never let an ungrounded answer through: every exact_quote must exist
  // verbatim in a retrieved chunk. Dropped citations downgrade the state.
  const { valid, droppedCount } = validateCitations(parsed.citations, retrieval);
  const answer = String(parsed.answer ?? "").trim();
  let status: "grounded" | "partially_supported" | "insufficient_evidence" =
    parsed.status === "grounded_response" ? "grounded" : "insufficient_evidence";

  if (status === "grounded" && droppedCount > 0) status = "partially_supported";
  if (answer.length === 0 || (valid.length === 0 && droppedCount > 0)) status = "insufficient_evidence";

  if (status === "insufficient_evidence") {
    return json({
      status: "insufficient_evidence",
      abstained: false,
      best_score: retrieval[0].score,
      threshold: ABSTENTION_THRESHOLD,
      answer: "",
      citations: [],
      retrieval,
      note: "The model could not answer from the retrieved chunks.",
    });
  }

  return json({
    status,
    abstained: false,
    best_score: retrieval[0].score,
    threshold: ABSTENTION_THRESHOLD,
    answer,
    citations: valid,
    retrieval,
  });
});
